package com.campus.lostfound.entity; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="notifications") public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User recipient; @Column(nullable=false,length=500) private String message; private boolean readFlag=false; private LocalDateTime createdAt=LocalDateTime.now(); protected Notification(){} public Notification(User u,String m){recipient=u;message=m;} public Long getId(){return id;} public User getRecipient(){return recipient;} public String getMessage(){return message;} public boolean isReadFlag(){return readFlag;} public void setReadFlag(boolean v){readFlag=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
